use super::*;use serde_json::json;
fn root()->std::path::PathBuf{std::env::current_dir().unwrap().join("effect-request-wire")}
fn question()->SourceQuery{SourceQuery::NativeEffectReports{environment:root().join("project.dme"),configuration:None,page_width:64,target_window:128}}
fn request()->QueryRequest{QueryRequest{analysis_context:None,timeout_seconds:Some(300),project:root().join("project.dme"),defines:Default::default(),engine_template:None,bootstrap_catalog:false,expected_revision:Some("1".repeat(32)),expected_source_revision:Some("2".repeat(32)),expected_policy_revision:Some("3".repeat(32)),queries:vec![],source_queries:vec![question()]}}
fn row()->Value{json!({"row":"source_native_effect_reports","schema":"dm-session-source-query-v1","semantic_revision":"semantic","source_revision":"source","policy_revision":"policy","environment":root().join("project.dme"),"configuration":root().join("SpacemanDMM.toml"),"configuration_explicit":false,"configuration_present":false,"configuration_schema":"complete_pinned_checker_schema","page_width":64,"target_window":128,"target_count":1,"body_count":1,"full_checker_parity":false,"effect_phase_order":["body_immediate","must_not_sleep","must_be_pure"],"target_group_order_contract":dm_analysis::checker_effects::TARGET_GROUP_ORDER_CONTRACT,"effect_report_only":true,"target_windows_exhausted":true,"diagnostics":[]})}
fn reply(row:&Value)->QueryReply{QueryReply{schema:"dm-session-query-v2".into(),revision:"semantic".into(),complete:false,coverage:"effect only".into(),query_count:0,source_query_count:1,source_revision:Some("source".into()),policy_revision:Some("policy".into()),snapshot_outcome:"analyzed".into(),last_request_outcome:"analyzed".into(),publication_pair:None,jsonl:format!("{row}\n")}}
#[test]fn effect_request_requires_all_pins_absolute_config_and_existing_window_bounds(){let mut r=request();r.validate().unwrap();r.expected_policy_revision=None;assert!(r.validate().is_err());r=request();r.expected_source_revision=None;assert!(r.validate().is_err());r=request();r.expected_revision=None;assert!(r.validate().is_err());for(page_width,target_window)in[(0,1),(1,0),(10001,1),(1,10001)]{r=request();r.source_queries=vec![SourceQuery::NativeEffectReports{environment:root().join("project.dme"),configuration:None,page_width,target_window}];assert!(r.validate().is_err());}r=request();r.source_queries=vec![SourceQuery::NativeEffectReports{environment:"relative.dme".into(),configuration:None,page_width:1,target_window:1}];assert!(r.validate().is_err());let encoded=serde_json::to_vec(&request()).unwrap();let decoded:QueryRequest=serde_json::from_slice(&encoded).unwrap();decoded.validate().unwrap();}
#[test]fn effect_reply_requires_exact_request_config_revisions_exhaustion_and_honest_partial_coverage(){let good=row();validate_requested(&reply(&good),&[question()]).unwrap();for(key,value)in[("policy_revision",json!("foreign")),("source_revision",json!("foreign")),("semantic_revision",json!("foreign")),("configuration",json!(root().join("other.toml"))),("configuration_explicit",json!(true)),("page_width",json!(1)),("target_window",json!(1)),("target_windows_exhausted",json!(false)),("full_checker_parity",json!(true)),("effect_report_only",json!(false))]{let mut bad=good.clone();bad[key]=value;assert!(validate_requested(&reply(&bad),&[question()]).is_err(),"{key}");}assert!(validate_requested(&reply(&good),&[]).is_err());let mut doubled=reply(&good);doubled.jsonl+=&doubled.jsonl.clone();assert!(validate_requested(&doubled,&[question()]).is_err());let mut bad=good;bad["diagnostics"]=json!([{"phase":"must_be_pure","registration_tag":"must_be_pure","family":"must_be_pure","severity":"error","source":{"file":"p.dm","line":1,"column":1},"expanded_span":[1,2],"expression_span":[1,2],"message":"pure","notes":[]},{"phase":"must_not_sleep","registration_tag":"must_not_sleep","family":"must_not_sleep","severity":"error","source":{"file":"p.dm","line":1,"column":1},"expanded_span":[1,2],"expression_span":[1,2],"message":"sleep","notes":[]}]);assert!(validate_requested(&reply(&bad),&[question()]).is_err());}

#[test]fn effect_request_keeps_existing_512k_transport_refusal_without_truncating_a_row(){use std::io::Write;assert_eq!(super::super::MAX_OUTPUT,524288);let mut output=super::super::BoundedOutput(b"prefix".to_vec());let error=output.write_all(&vec![b'x';super::super::MAX_OUTPUT]).unwrap_err();assert!(error.to_string().contains("512 KiB"));assert_eq!(output.0,b"prefix");}
